-- Denmark source-backed checklist; additive, preserves existing administrator edits. Requires base 001 and source fields 002.
alter table public.countries add column if not exists is_schengen boolean not null default false;
alter table public.country_documents add column if not exists source_checked_at date;
alter table public.country_documents add column if not exists topic_ids text[] not null default '{}';
insert into public.countries(id,name,code,flag,is_schengen) values('denmark','Danimarka','DK','🇩🇰',true) on conflict(id) do nothing;
insert into public.country_documents(id,country_id,title,body,category,source_url,visa_type,sort_order,requirement,source_name,source_document,source_type,source_scope,source_updated_at,source_checked_at,topic_ids)
select id,country_id,title,body,category,source_url,visa_type,sort_order,requirement,source_name,source_document,source_type,source_scope,source_updated_at,source_checked_at,topic_ids from jsonb_to_recordset($docs$[{"id": "d4588156-fdaf-58d9-8c1d-e9584f7ef6dc", "country_id": "denmark", "key": "passport", "title": "Pasaport", "body": "Pasaportun planlanan ayrılıştan sonra en az 3 ay geçerli, son 10 yıl içinde düzenlenmiş ve en az 2 boş sayfalı olmalı. Vize geçerlilik dönemiyle uyumunu resmî talimattan kontrol et.", "requirement": "required", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 1, "source_url": "https://www.nyidanmark.dk/en-GB/You-want-to-apply/Short-stay-visa/Private-visits-and-tourist-visits-", "source_name": "Danimarka Göçmenlik Servisi – Özel ziyaret ve turistik vize", "source_document": "Danimarka genel vize koşulları ve vatandaşlık grupları", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": ["passport"], "alert": null}, {"id": "7e2721e6-21d1-5ee4-a3ef-ce8c97d3a284", "country_id": "denmark", "key": "form", "title": "Başvuru formu", "body": "Danimarka Dışişleri Bakanlığı ApplyVisa portalında başvuru formunu doldur. Portalın verdiği başvuru/ödeme belgesini ve imza talimatını izle; belge teslimi ve biyometri randevusu ayrı adımdır.", "requirement": "required", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 2, "source_url": "https://applyvisa.um.dk/", "source_name": "Danimarka Dışişleri Bakanlığı – ApplyVisa", "source_document": "Resmî çevrimiçi başvuru portalı", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": [], "alert": null}, {"id": "24708bd9-ef14-53da-bfc3-9d826a78a9b6", "country_id": "denmark", "key": "photo", "title": "Biyometrik fotoğraf", "body": "Danimarka resmî sayfası 35 × 45 mm güncel fotoğraf ister; çeneden başın üstüne mesafe 30–36 mm olmalı. Yüz kameraya dönük ve mevcut görünümünü yansıtmalı.", "requirement": "required", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 3, "source_url": "https://www.nyidanmark.dk/en-GB/You-want-to-apply/Short-stay-visa/Private-visits-and-tourist-visits-", "source_name": "Danimarka Göçmenlik Servisi – Özel ziyaret ve turistik vize", "source_document": "Danimarka genel vize koşulları ve vatandaşlık grupları", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": [], "alert": null}, {"id": "8d9b2d1a-3c79-5b11-9816-b60785f6e56d", "country_id": "denmark", "key": "insurance", "title": "Seyahat sağlık sigortası", "body": "Bütün Schengen ülkelerinde ve seyahat süresinin tamamında geçerli, en az 30.000 € teminatlı seyahat sağlık sigortası hazırla. Acil tedavi, hastane ve sağlık/vefat nedeniyle geri dönüşü kapsamalı.", "requirement": "required", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 4, "source_url": "https://www.nyidanmark.dk/en-GB/You-want-to-apply/Short-stay-visa/Private-visits-and-tourist-visits-", "source_name": "Danimarka Göçmenlik Servisi – Özel ziyaret ve turistik vize", "source_document": "Danimarka genel vize koşulları ve vatandaşlık grupları", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": [], "alert": null}, {"id": "bcd92ba7-5ae5-58aa-8d42-efee83106e15", "country_id": "denmark", "key": "itinerary", "title": "Ulaşım rezervasyonu ve seyahat planı", "body": "Uçuş rezervasyonu, planlanan diğer ulaşım araçlarına ilişkin kanıt veya seyahat güzergâhını sun. Birden fazla ülke varsa aradaki yolculukları ve kalış tarihlerini açıkla.", "requirement": "required", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 5, "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": [], "alert": null}, {"id": "a110301c-23ba-56ae-9bb0-8a56f78cecc6", "country_id": "denmark", "key": "accommodation", "title": "Konaklama ve davet mektubu", "body": "Seyahatin tamamına ait konaklama kanıtını sun. Bir ev sahibini ziyaret ediyorsan davet mektubu veya çevrimiçi davet kimliği ile ilişkinizi gösteren belgeleri ekle. Türkiye için Grup 3 ziyaret koşullarını kontrol et; otel rezervasyonu davet/ilişki koşulunun yerine otomatik geçmez.", "requirement": "required", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 6, "source_url": "https://www.nyidanmark.dk/en-GB/You-want-to-apply/Short-stay-visa/Private-visits-and-tourist-visits-", "source_name": "Danimarka Göçmenlik Servisi – Özel ziyaret ve turistik vize", "source_document": "Danimarka genel vize koşulları ve vatandaşlık grupları", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": ["invitation"], "alert": {"title": "Türkiye için ev sahibi ve ziyaret koşullarını kontrol et", "body": "Resmî Danimarka sayfası Türkiye’yi Grup 3 içinde sayar; özel ziyaretlerde ev sahibiyle belirli bir ilişki beklenir. Başvuru amacına uygun koşulları ve varsa istisnaları resmî sayfadan kontrol et.", "source_url": "https://www.nyidanmark.dk/en-GB/You-want-to-apply/Short-stay-visa/Private-visits-and-tourist-visits-"}}, {"id": "cc4a22a7-6a6c-5dbc-b898-5614edb08780", "country_id": "denmark", "key": "finance", "title": "Maddi durum ve banka hesap dökümleri", "body": "Son 3 aylık banka hareketleri ve gelir kanıtlarını hazırla. Danimarka genel yaklaşım olarak günlük yaklaşık 350 DKK, otelde kalışta yaklaşık 500 DKK belirtir; tutar seyahat ve masraf paylaşımına göre değerlendirilir, tek başına vize garantisi değildir.", "requirement": "required", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 7, "source_url": "https://www.nyidanmark.dk/en-GB/You-want-to-apply/Short-stay-visa/Private-visits-and-tourist-visits-", "source_name": "Danimarka Göçmenlik Servisi – Özel ziyaret ve turistik vize", "source_document": "Danimarka genel vize koşulları ve vatandaşlık grupları", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": ["finance", "sponsor"], "alert": null}, {"id": "4029de1a-1c97-5f24-9287-3e22501cfdc7", "country_id": "denmark", "key": "employment", "title": "Çalışan, şirket sahibi, emekli veya çiftçi belgeleri", "body": "Durumuna göre: çalışan için işveren/izin yazısı, SGK işe giriş ve okunabilir QR kodlu hizmet dökümü; şirket sahibi için oda/ticaret sicil kaydı, vergi ve faaliyet belgeleri; emekli için emekli maaşı kanıtı; çiftçi için ziraat odası belgesi sun. Hepsi her başvuran için birlikte istenmez.", "requirement": "conditional", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 8, "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": ["employment"], "alert": null}, {"id": "dd13af83-8aa3-5200-93bd-fcffb92fb695", "country_id": "denmark", "key": "student", "title": "Öğrenci belgesi", "body": "Öğrenciysen güncel öğrenci belgeni hazırla. Yükseköğretim için YÖK tarafından düzenlenen, okunabilir QR kodlu öğrenci belgesi; diğer öğrenciler için okul belgesi ortak Türkiye listesinde yer alır.", "requirement": "conditional", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 9, "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": ["student"], "alert": null}, {"id": "419852db-f7d8-5f98-bc05-df4529b5f351", "country_id": "denmark", "key": "registry", "title": "Tam tekmil vukuatlı nüfus kayıt örneği", "body": "Ortak Türkiye destekleyici belge listesinde tam tekmil vukuatlı nüfus kayıt örneği bulunur. Ülkenin listesinde belirtilen format, tercüme ve aile bağı belgelerini ayrıca kontrol et.", "requirement": "required", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 10, "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": [], "alert": null}, {"id": "8a03a783-3a3d-5289-9a52-953d7d328373", "country_id": "denmark", "key": "sponsor", "title": "Sponsor ve masraf karşılama belgeleri", "body": "Masrafları ev sahibi veya sponsor karşılayacaksa hangi giderleri üstlendiğini ve kaynaklarını belgele. Danimarka özel ziyaretlerde VU2 davet formunu tavsiye eder; formun kendisi zorunlu değildir. Davet/ev sahibi ve ilişkinin koşulları ayrıca değerlendirilir.", "requirement": "conditional", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 11, "source_url": "https://www.nyidanmark.dk/en-GB/You-want-to-apply/Short-stay-visa/Private-visits-and-tourist-visits-", "source_name": "Danimarka Göçmenlik Servisi – Özel ziyaret ve turistik vize", "source_document": "Danimarka genel vize koşulları ve vatandaşlık grupları", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": ["sponsor"], "alert": null}, {"id": "9c328a96-1870-544c-9f33-c078ccc31254", "country_id": "denmark", "key": "minors", "title": "18 yaş altı başvuruları", "body": "18 yaşından küçük kişi tek başına, yalnız bir ebeveynle veya yasal vasiyle seyahat ediyorsa seyahat etmeyen ebeveyn/vasinin noter onaylı izni ya da tek velayeti kanıtlayan belge gerekir. Tek velayet ve diğer istisnaları belgelendir.", "requirement": "conditional", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 12, "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": [], "alert": null}, {"id": "4f48b323-1598-5494-abd4-33d6132ce1ba", "country_id": "denmark", "key": "residence", "title": "Türkiye’de yasal ikamet belgesi", "body": "Türk vatandaşı değilsen, ortak Türkiye listesine göre Schengen’den planlanan ayrılıştan en az 3 ay sonrasına kadar geçerli Türkiye ikamet belgesini sun. Başvuru yetkisini ve vatandaşlığına göre istisnaları resmî temsilcilikten kontrol et.", "requirement": "conditional", "category": "Turistik vize", "visa_type": "tourism_c", "sort_order": 13, "source_url": "https://consistanbul.esteri.it/wp-content/uploads/2026/05/TURCHIA_EN-Harmonized-List.pdf", "source_name": "Avrupa Komisyonu C(2021) 5156 – Türkiye destekleyici belge listesi", "source_document": "Türkiye’den başvurular; İtalya Başkonsolosluğu’nun yayımladığı resmî kopya", "source_type": "official", "source_scope": "Danimarka resmî sayfasında Türkiye Grup 3 içinde yer alır; özel ziyaretlerde ev sahibiyle ilişki koşulları bulunur. Turizm ve ziyaret amacına uygun başvuru yolunu kontrol et.", "source_updated_at": null, "source_checked_at": "2026-10-27", "topic_ids": [], "alert": null}]$docs$::jsonb) as d(id uuid,country_id text,title text,body text,category text,source_url text,visa_type text,sort_order integer,requirement text,source_name text,source_document text,source_type text,source_scope text,source_updated_at date,source_checked_at date,topic_ids text[]) on conflict(id) do nothing;
notify pgrst,'reload schema';
